#!/usr/bin/env python3
"""Residents survey crosstabs: python3 crosstabs.py INPUT_DIR OUTPUT_FILE"""
import csv
import io
import json
import sys
from datetime import datetime, timedelta, timezone
from pathlib import Path


def load_json(p):
    with open(p, encoding="utf-8-sig") as f:
        return json.load(f)


def read_export(path):
    text = Path(path).read_bytes().decode("utf-8-sig")
    first = text.split("\n", 1)[0]
    delim = next((d for d in (",", ";", "\t") if d in first), ",")
    rows = []
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
    header = None
    for cells in reader:
        cells = [c.strip() for c in cells]
        if header is None:
            header = cells
            continue
        if not any(cells):
            continue
        cells += [""] * (len(header) - len(cells))
        row = {}
        for h, c in zip(header, cells):
            if h not in row:
                row[h] = c
        rows.append(row)
    return rows


def parse_offset(s):
    sign = -1 if s[0] == "-" else 1
    hh, mm = s[1:].split(":")
    return timezone(sign * timedelta(hours=int(hh), minutes=int(mm)))


def parse_time(s, meta):
    s = s.strip()
    if meta.get("submitted_format") == "local":
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        return dt.replace(tzinfo=parse_offset(meta["utc_offset"]))
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def parse_duration(s, meta):
    if meta.get("duration_format") == "clock":
        parts = [int(p) for p in s.split(":")]
        t = 0
        for p in parts:
            t = t * 60 + p
        return t
    return int(float(s))


def median(vals):
    v = sorted(vals)
    n = len(v)
    if n % 2:
        return v[n // 2]
    return (v[n // 2 - 1] + v[n // 2]) / 2


def to_code(v, recode):
    if recode is not None:
        return recode[v]
    return int(v)


def main(indir, outfile):
    indir = Path(indir)
    cb = load_json(indir / "codebook.json")
    wt = load_json(indir / "weighting.json")
    plan = load_json(indir / "tables.json")
