    vkeys = list(versions)
    questions = cb["questions"]
    qmap = {q["id"]: q for q in questions}

    # 1. read rows
    rows = []
    exp = indir / "exports"
    files = sorted(p for p in exp.iterdir() if p.is_file() and p.name.endswith(".csv")) if exp.is_dir() else []
    for p in files:
        for r in read_export(p):
            v = r.get("form_version", "")
            meta = versions[v]["meta"]
            rid = r.get(meta["id"], "")
            complete = r.get(meta["status"], "") == meta["complete"]
            row = {"v": v, "raw": r, "id": rid, "complete": complete,
                   "time": parse_time(r[meta["submitted"]], meta)}
            lp = r.get(meta["last_page"], "")
            row["last_page"] = int(float(lp)) if lp else 0
            if complete:
                row["last_page"] = versions[v]["pages"]
            d = r.get(meta["duration"], "")
            row["duration"] = parse_duration(d, meta) if d else None
            rows.append(row)

    stats = {k: {"rows": 0, "duplicates": 0, "short_partials": 0, "speeders": 0,
                 "complete": 0, "partial": 0} for k in vkeys}
    for r in rows:
        stats[r["v"]]["rows"] += 1

    # 2. duplicates
    best = {}
    for r in rows:
        cur = best.get(r["id"])
        if cur is None or (r["complete"], r["time"]) > (cur["complete"], cur["time"]):
            best[r["id"]] = r
    kept = []
    for r in rows:
        if best[r["id"]] is r:
            kept.append(r)
        else:
            stats[r["v"]]["duplicates"] += 1
    # 3. short partials
