    k2 = []
    for r in kept:
        if not r["complete"] and r["last_page"] < mp:
            stats[r["v"]]["short_partials"] += 1
        else:
            k2.append(r)
    # 4. speeders
    med = {}
    for v in vkeys:
        ds = [r["duration"] for r in k2 if r["v"] == v and r["complete"] and r["duration"] is not None]
        med[v] = median(ds) if ds else None
    k3 = []
    for r in k2:
