        if t == "multi":
            chosen = set()
            if "columns" in entry:
                for code, col in entry["columns"].items():
                    if raw.get(col, "") == "1":
                        chosen.add(int(code))
            else:
                cell = raw.get(entry["column"], "")
                for el in cell.split(entry["separator"]):
                    el = el.strip()
                    if el:
                        chosen.add(to_code(el, recode))
            if not chosen:
                return None
            opts = {o["code"]: o for o in q["options"]}
            excl = {c for c in chosen if opts[c].get("exclusive")}
            if excl and len(excl) < len(chosen):
                chosen -= excl
            elif len(excl) >= 2 and len(excl) == len(chosen):
                return None
            chosen = {c for c in chosen if not opts[c].get("missing")}
            return chosen or None
        val = raw.get(entry["column"], "")
        if val == "":
            return None
        if t == "age":
            src = entry.get("source")
            if src == "band":
